using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTest.Features.LoyaltyDiscount;

public sealed class CalculateLoyaltyDiscountAcceptanceTests
{
    private readonly CalculateLoyaltyDiscount _useCase = new();

    private int Charged(LoyaltyTier tier, int subtotalCents) =>
        _useCase.Handle(new CalculateLoyaltyDiscountQuery(subtotalCents, tier)).TotalCents;

    // Bronze customer is charged 9500 cents on a 10000 cent basket
    [Fact]
    public void S1_BronzeBasketOf10000IsCharged9500()
    {
        Assert.Equal(9500, Charged(LoyaltyTier.Bronze, 10000));
    }

    // Silver customer is charged 9000 cents on a 10000 cent basket
    [Fact]
    public void S2_SilverBasketOf10000IsCharged9000()
    {
        Assert.Equal(9000, Charged(LoyaltyTier.Silver, 10000));
    }

    // Gold customer is charged 8500 cents on a 10000 cent basket
    [Fact]
    public void S3_GoldBasketOf10000IsCharged8500()
    {
        Assert.Equal(8500, Charged(LoyaltyTier.Gold, 10000));
    }

    // Bronze customer is charged 7 cents on a 7 cent basket
    [Fact]
    public void S4_BronzeBasketOf7IsCharged7()
    {
        Assert.Equal(7, Charged(LoyaltyTier.Bronze, 7));
    }
}

